#!/usr/bin/env node
/**
 * MCP stdio bridge to a blobfish.ai-generated simulation world.
 *
 * The world (tables, tools, tasks, verifiers) is generated by the blobfish.ai API and
 * runs either hosted (blobfish.ai) or locally via the downloaded self-contained package
 * (world/blobfish/package/<id>/server.py). Both expose the same MCP-over-HTTP endpoint;
 * this bridge proxies it to stdio and adds two HARNESS tools: verify_task (VCode
 * ground-truth scoring, fed the accumulated rollout trace) and reset_session.
 *
 * Modes:
 *   hosted (default): needs BLOBFISH_API_KEY in .env and blobfish.worldId in config.
 *   local:  set BLOBFISH_LOCAL=1 — targets config.blobfish.localBase (packaged server).
 */
import { readFileSync } from "node:fs";
import { createInterface } from "node:readline";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const config = JSON.parse(readFileSync(join(ROOT, "config", "world.config.json"), "utf8"));

function envFile() {
  try {
    return Object.fromEntries(
      readFileSync(join(ROOT, ".env"), "utf8").split("\n")
        .map((l) => l.trim()).filter((l) => /^[A-Z0-9_]+=/.test(l))
        .map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1)])
    );
  } catch { return {}; }
}
const env = { ...envFile(), ...process.env };
const LOCAL = env.BLOBFISH_LOCAL === "1" || env.BLOBFISH_LOCAL === "true";
const KEY = env.BLOBFISH_API_KEY;
const WORLD_ID = env.BLOBFISH_WORLD_ID ?? config.blobfish.worldId;
if (!LOCAL && (!KEY || !WORLD_ID || WORLD_ID === "PENDING")) {
  process.stderr.write("[blobfish-bridge] hosted mode needs BLOBFISH_API_KEY and config.blobfish.worldId (or set BLOBFISH_LOCAL=1)\n");
  process.exit(1);
}
const WORLD_BASE = LOCAL
  ? (env.BLOBFISH_LOCAL_BASE ?? config.blobfish.localBase ?? "http://127.0.0.1:8971")
  : `${config.blobfish.api}/sandbox/worlds/${WORLD_ID}`;
const MCP_URL = `${WORLD_BASE}/mcp`;

let SESSION = null;
let TOOLS = [];
let UPSTREAM_INFO = {};
let upstreamId = 1000;
const TRACE = []; // verifier-grade rollout trace: {tool, requested_tool, arguments, observation, ok}

const HARNESS_TOOLS = [
  {
    name: "verify_task",
    description: "HARNESS ONLY: score the current world state + rollout trace against a task's ground truth using blobfish's VCode verifier. Call once at the end of a rollout with the task_id.",
    inputSchema: { type: "object", properties: { task_id: { type: "string" } }, required: ["task_id"] },
  },
  {
    name: "reset_session",
    description: "HARNESS ONLY: reset the world session state for a fresh rollout.",
    inputSchema: { type: "object", properties: {} },
  },
];

function normSchema(s) {
  // LLM APIs require a root object schema; repair anything else.
  if (!s || typeof s !== "object" || Array.isArray(s)) return { type: "object", properties: {} };
  if (s.type === "object") return { properties: {}, ...s };
  if (s.properties) return { ...s, type: "object" };
  return { type: "object", properties: {} };
}

function authHeaders() {
  return {
    ...(KEY ? { "X-API-Key": KEY } : {}),
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    ...(SESSION ? { "Mcp-Session-Id": SESSION, "X-Blobfish-Session": SESSION } : {}),
  };
}

/** POST a JSON-RPC message to the upstream MCP endpoint; returns the matching response message. */
async function mcpUpstream(method, params, { timeoutMs = 170000, notification = false } = {}) {
  const id = notification ? undefined : ++upstreamId;
  const body = JSON.stringify({ jsonrpc: "2.0", ...(notification ? {} : { id }), method, params });
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(MCP_URL, { method: "POST", headers: authHeaders(), body, signal: ctrl.signal });
    const ctype = res.headers.get("content-type") ?? "";
    const text = await res.text();
    if (notification) return null;
    if (!res.ok) throw new Error(`upstream MCP HTTP ${res.status}: ${text.slice(0, 300)}`);
    let messages = [];
    if (ctype.includes("text/event-stream")) {
      for (const chunk of text.split("\n")) {
        const line = chunk.trim();
        if (line.startsWith("data:")) {
          try { messages.push(JSON.parse(line.slice(5).trim())); } catch { /* partial frame */ }
        }
      }
    } else {
      try { messages = [JSON.parse(text)]; } catch { throw new Error(`upstream MCP non-JSON reply: ${text.slice(0, 300)}`); }
    }
    const match = messages.find((m) => m.id === id) ?? messages.find((m) => m.result !== undefined || m.error !== undefined);
    if (!match) throw new Error("upstream MCP: no response message found");
    if (match.error) throw new Error(`upstream MCP ${match.error.code}: ${match.error.message}`);
    return match.result;
  } finally {
    clearTimeout(t);
  }
}

/** Plain REST call against the world (sessions/verify are not MCP methods). */
async function rest(path, opts = {}) {
  const res = await fetch(`${WORLD_BASE}${path}`, { ...opts, headers: { ...authHeaders(), ...(opts.headers ?? {}) } });
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch { /* non-JSON body */ }
  return { ok: res.ok, status: res.status, text, json };
}

async function createSession() {
  const s = await rest("/sessions", { method: "POST", body: "{}" });
  if (!s.ok) throw new Error(`session create ${s.status}: ${s.text.slice(0, 300)}`);
  return s.json.session_id ?? s.json.sessionId ?? null;
}

async function boot() {
  SESSION = await createSession();
  const init = await mcpUpstream("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "blobfish-crm-bridge", version: "2.1.0" },
  }, { timeoutMs: 30000 });
  UPSTREAM_INFO = { serverInfo: init.serverInfo, world: init.world ?? {} };
  await mcpUpstream("notifications/initialized", {}, { notification: true });

  const list = await mcpUpstream("tools/list", {}, { timeoutMs: 60000 });
  TOOLS = (list.tools ?? []).map((t) => ({
    name: t.name,
    description: t.description ?? "",
    inputSchema: normSchema(t.inputSchema ?? t.input_schema),
  }));
  process.stderr.write(`[blobfish-bridge] ${LOCAL ? "LOCAL" : "hosted"} world ${UPSTREAM_INFO.world.worldId ?? WORLD_ID} (${UPSTREAM_INFO.world.company ?? "?"}) — ${TOOLS.length} world tools, session ${SESSION}\n`);
}

// --------------------------------------------------------------- MCP plumbing
const SERVER_INFO = { name: "blobfish-crm-bridge", version: "2.1.0" };
const send = (msg) => process.stdout.write(JSON.stringify(msg) + "\n");
const reply = (id, result) => send({ jsonrpc: "2.0", id, result });
const replyErr = (id, code, message) => send({ jsonrpc: "2.0", id, error: { code, message } });
const toolResult = (id, ok, text) => reply(id, { content: [{ type: "text", text }], isError: !ok });
const clipObs = (s) => (typeof s === "string" && s.length > 4000 ? s.slice(0, 4000) : s);

async function handle(msg) {
  const { id, method, params = {} } = msg;
  const isNotification = id === undefined || id === null;
  try {
    switch (method) {
      case "initialize":
        return reply(id, {
          protocolVersion: params.protocolVersion ?? "2025-06-18",
          capabilities: { tools: { listChanged: false }, resources: {} },
          serverInfo: SERVER_INFO,
          instructions:
            `Bridge to blobfish world ${WORLD_ID} ("${UPSTREAM_INFO.world.company ?? "simulated org"}") — a fully synthetic ` +
            `Salesforce-CRM-style simulation (Morgan Stanley (SIMULATED) scenario; no real entities). ` +
            `Tools execute against the ${LOCAL ? "locally packaged" : "hosted"} world state. ` +
            `Tools marked HARNESS ONLY are for the evaluation harness, not the agent.`,
        });
      case "notifications/initialized":
      case "notifications/cancelled":
        return;
      case "ping":
        return reply(id, {});
      case "tools/list":
        return reply(id, { tools: [...TOOLS, ...HARNESS_TOOLS] });
      case "tools/call": {
        const name = params.name;
        const args = params.arguments ?? {};
        if (name === "verify_task") {
          const path = LOCAL ? `/verify/${encodeURIComponent(args.task_id)}` : "/verify";
          const body = LOCAL ? { trace: TRACE } : { task_id: args.task_id, trace: TRACE };
          const r = await rest(path, { method: "POST", body: JSON.stringify(body) });
          return toolResult(id, r.ok, r.json ? JSON.stringify(r.json, null, 2) : r.text);
        }
        if (name === "reset_session") {
          if (LOCAL) await rest(`/sessions/${SESSION}`, { method: "DELETE" });
          else await rest(`/sessions/${SESSION}/reset`, { method: "GET" });
          SESSION = await createSession();
          TRACE.length = 0;
          return toolResult(id, true, JSON.stringify({ reset: true, session: SESSION }));
        }
        if (!TOOLS.some((t) => t.name === name)) return replyErr(id, -32602, `Unknown tool '${name}'`);
        const bareName = name.includes(".") ? name.split(".").pop() : name; // verifiers match un-namespaced tool names
        try {
          const result = await mcpUpstream("tools/call", { name, arguments: args });
          const obsText = (result?.content ?? []).map((c) => c.text ?? "").join("\n");
          TRACE.push({ tool: bareName, requested_tool: name, arguments: args, observation: clipObs(obsText), ok: !result?.isError });
          return reply(id, result);
        } catch (e) {
          TRACE.push({ tool: bareName, requested_tool: name, arguments: args, observation: `ERROR: ${e.message}`, ok: false });
          // Surface upstream failures as tool-level errors so the agent can adapt.
          return toolResult(id, false, `ERROR: ${e.message}`);
        }
      }
      case "resources/list":
        return reply(id, { resources: [{ uri: "blobfish://world/meta", name: "World metadata", mimeType: "application/json" }] });
      case "resources/read":
        if (params.uri === "blobfish://world/meta") {
          return reply(id, { contents: [{ uri: params.uri, mimeType: "application/json", text: JSON.stringify({ worldId: WORLD_ID, mode: LOCAL ? "local" : "hosted", ...UPSTREAM_INFO, session: SESSION, toolCount: TOOLS.length, traceLength: TRACE.length }, null, 2) }] });
        }
        return replyErr(id, -32602, `Unknown resource '${params.uri}'`);
      default:
        if (!isNotification) return replyErr(id, -32601, `Method not found: ${method}`);
    }
  } catch (e) {
    if (!isNotification) return replyErr(id, -32603, `Bridge error: ${e.message}`);
    process.stderr.write(`[blobfish-bridge] error in ${method}: ${e.stack}\n`);
  }
}

boot()
  .then(() => {
    const rl = createInterface({ input: process.stdin, terminal: false });
    rl.on("line", (line) => {
      if (!line.trim()) return;
      let msg;
      try { msg = JSON.parse(line); } catch { return replyErr(null, -32700, "Parse error"); }
      handle(msg).catch((e) => process.stderr.write(`[blobfish-bridge] unhandled: ${e.stack}\n`));
    });
    rl.on("close", () => process.exit(0));
  })
  .catch((e) => {
    process.stderr.write(`[blobfish-bridge] boot failed: ${e.message}\n`);
    process.exit(1);
  });
